export function sensorSpecForPart(part) {
  if (!part || typeof part !== 'object') return null;
  const keys = [part.asin, part.id, part.listingId]
    .filter((value) => typeof value === 'string' && value.trim())
    .map((value) => value.trim().toUpperCase());
  return keys.map((key) => sensorSpecsByIdentity[key]).find(Boolean) || null;
}

export default sensorSpecsByIdentity;
